#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> qoshni(n + 1);
    for (int k = 0; k < m; k++) {
        int u, v;
        cin >> u >> v;
        qoshni[u].push_back(v);
        qoshni[v].push_back(u);
    }
    for (int i = 1; i <= n; i++) {
        sort(qoshni[i].begin(), qoshni[i].end());
        cout << qoshni[i].size();
        for (int x : qoshni[i]) cout << " " << x;
        cout << endl;
    }
    return 0;
}
